const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/todos',
  headers: {'content-type': 'application/json'},
  body: {
    project_id: 1,
    todo: {
      assignment_id: 1,
      color: '#314159',
      description: 'Use some power tools to fix the drywall.',
      finish_datetime: '2015-02-07T00:00:00Z',
      name: 'Fix drywall',
      percentage: 99,
      private: true,
      start_datetime: '2015-02-06T00:00:00Z'
    }
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/todos"),
    Content = new StringContent("{\"project_id\":1,\"todo\":{\"assignment_id\":1,\"color\":\"#314159\",\"description\":\"Use some power tools to fix the drywall.\",\"finish_datetime\":\"2015-02-07T00:00:00Z\",\"name\":\"Fix drywall\",\"percentage\":99,\"private\":true,\"start_datetime\":\"2015-02-06T00:00:00Z\"}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

